import re


def audit_artipacked(record):
    """Return json-v1 artipacked findings for a normalized input record."""
    get = record.get if isinstance(record, dict) else lambda k, default=None: getattr(record, k, default)
    if get("kind") not in ("workflow", "workflows"):
        return []
    text = get("text", "")
    path = get("path", "")
    lines = text.splitlines(keepends=True)
    findings = []
    job = None
    steps_index = -1
    in_steps = False
    in_jobs = False
    current_step = None
    step_has_checkout = False
    step_configured = False

    def finish_step():
        if current_step is None or not step_has_checkout or step_configured:
            return
        line_no, column, end_column, raw, ref = current_step
        offset = sum(len(s) for s in lines[:line_no])
        route = [{"Key": "jobs"}, {"Key": job or ""}, {"Key": "steps"}, {"Index": steps_index}]
        feat = lines[line_no][column:]
        comment = None
        quote = None
        for i, char in enumerate(raw):
            if quote:
                if char == quote and (i == 0 or raw[i - 1] != "\\"):
                    quote = None
            elif char in ("'", '"'):
                quote = char
            elif char == "#" and (i == 0 or raw[i - 1].isspace()):
                comment = raw[i:].strip()
                break
        if lines[line_no].endswith(("\n", "\r")):
            end_point = {"row": line_no + 1, "column": 0}
            absolute_end = offset + len(lines[line_no])
        else:
            end_point = {"row": line_no, "column": len(raw)}
            absolute_end = offset + len(raw)
        v6 = bool(re.search(r"@v([6-9]|[1-9][0-9]+)(?:\.|$)", ref, re.I))
        findings.append({
            "ident": "artipacked",
            "desc": "credential persistence through GitHub Actions artifacts",
            "url": "https://docs.zizmor.sh/audits/#artipacked",
            "determinations": {"confidence": "Low", "severity": "Low" if v6 else "Medium", "persona": "Regular"},
            "locations": [{
                "symbolic": {
                    "key": {"Local": {"prefix": None, "given_path": path}},
                    "annotation": "does not set persist-credentials: false",
                    "route": {"route": route}, "feature_kind": "Normal", "kind": "Primary",
                },
                "concrete": {
                    "location": {
                        "start_point": {"row": line_no, "column": column},
                        "end_point": end_point,
                        "offset_span": {"start": offset + column, "end": absolute_end},
                    },
                    "feature": feat, "comments": [comment] if comment else [],
                },
            }],
            "ignored": False,
        })

    for n, rawline in enumerate(lines):
        line = rawline.rstrip("\r\n")
        indent = len(line) - len(line.lstrip(" "))
        m = re.match(r"\s*([\w.-]+):\s*(?:#.*)?$", line)
        if indent == 0 and line.strip() == "jobs:":
