        if in_jobs and indent == 2 and m and m.group(1) != "steps":
            finish_step()
            current_step = None
            job = m.group(1)
            step_has_checkout = False
            step_configured = False
            steps_index = -1
        if indent == 4 and line.strip() == "steps:":
            finish_step()
            current_step = None
            in_steps = True
        if in_steps and indent == 6 and re.match(r"-\s", line.lstrip()):
            finish_step()
